    private static final RowMapper<IdemRecord> IDEM_MAPPER = (rs, n) -> new IdemRecord(
            rs.getString("request_id"), rs.getString("endpoint"), rs.getString("fingerprint"),
            rs.getInt("response_status"), rs.getString("response_body"));

